-- AutoFocus
('autofocus.eyebrow','home','Uzmanlık · Otomotiv','Expertise · Automotive'),
('autofocus.title.pre','home','Oto yedek parçada','No more waiting'),
('autofocus.title.em','home','artık','for'),
('autofocus.title.post','home','bekleme yok.','auto spare parts.'),
('autofocus.lead','home','Türkiye''de bulunamayan, üretimi durmuş ya da yurt dışından beklenen oto yedek parçaları <s>3 boyutlu olarak yeniden üretiyoruz.</s> Mevcut bir parçayı tarıyor, mühendislik düzeltmesini yapıyor ve kullanıma uygun malzeme ile basıyoruz.','We <s>re-manufacture in 3D</s> the auto spare parts that are unavailable in Turkey, out of production, or awaited from abroad. We scan the existing part, apply engineering corrections and print it in a fit-for-purpose material.'),
('autofocus.p1','home','Üretimi durmuş klasik araç parçaları','Discontinued classic-car parts'),
('autofocus.p2','home','Bulunamayan iç-dış trim parçaları','Hard-to-find interior/exterior trim'),
('autofocus.p3','home','Kırık tutucu, klips, braket ve aparatlar','Broken holders, clips, brackets and fixtures'),
('autofocus.p4','home','Motor odası — emme, kapak, mahfaza parçaları','Engine bay — intake, cover and housing parts'),
('autofocus.p5','home','Saç, plastik, kompozit eşdeğer üretim','Sheet, plastic, composite equivalent production'),
('autofocus.cta','home','Detaylı bilgi & örnek vakalar','Details & case studies'),
('autofocus.image.alt','home','3D baskı ile yeniden üretilmiş klasik araç yedek parçaları','Classic-car spare parts re-manufactured via 3D printing'),
